import java.util.*;

class Solution {
    public List<List<Integer>> distinctOrderings(int[] nums) {
        Arrays.sort(nums);                  // equal values side by side
        List<List<Integer>> out = new ArrayList<>();
        go(nums, new boolean[nums.length], new ArrayList<Integer>(), out);
        return out;
    }

    private void go(int[] nums, boolean[] used, List<Integer> cur, List<List<Integer>> out) {
        if (cur.size() == nums.length) { out.add(new ArrayList<>(cur)); return; }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;
            // use equal copies only in left-to-right order
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
            used[i] = true;
            cur.add(nums[i]);
            go(nums, used, cur, out);
            cur.remove(cur.size() - 1);
            used[i] = false;
        }
    }
}

