class Solution:
    def distinctOrderings(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        out, cur, used = [], [], [False] * len(nums)
        def go():
            if len(cur) == len(nums): out.append(cur[:]); return
            for i in range(len(nums)):
                if used[i] or (i > 0 and nums[i] == nums[i - 1] and not used[i - 1]): continue
                used[i] = True; cur.append(nums[i]); go(); cur.pop(); used[i] = False
        go()
        return out

