function distinctOrderings(nums) {
  const cnt = new Map(); for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);
  const out = [], cur = [];
  (function go() {
    if (cur.length === nums.length) { out.push(cur.slice()); return; }
    for (const [v, c] of cnt) if (c > 0) { cnt.set(v, c - 1); cur.push(v); go(); cur.pop(); cnt.set(v, c); }
  })();
  return out;
}
